<?php
if (!defined('ABSPATH')) { exit; }
add_action('init', static function (): void {
    foreach (['_oubei_seo_title', '_oubei_seo_description'] as $key) { register_post_meta('post', $key, ['type' => 'string', 'single' => true, 'show_in_rest' => true, 'sanitize_callback' => 'sanitize_text_field', 'auth_callback' => static fn(bool $allowed, string $meta_key, int $post_id): bool => current_user_can('edit_post', $post_id)]); }
});
add_action('add_meta_boxes_post', static function (): void { add_meta_box('oubei-post-seo', __('Oubei SEO', 'oubei'), static function (WP_Post $post): void { wp_nonce_field('oubei_save_post_seo', 'oubei_post_seo_nonce'); ?><p><label>SEO title<br><input class="widefat" name="oubei_seo_title" value="<?php echo esc_attr((string) get_post_meta($post->ID, '_oubei_seo_title', true)); ?>"></label></p><p><label>SEO description<br><textarea class="widefat" name="oubei_seo_description"><?php echo esc_textarea((string) get_post_meta($post->ID, '_oubei_seo_description', true)); ?></textarea></label></p><?php }, 'post', 'normal'); });
add_action('save_post_post', static function (int $post_id): void { if (!isset($_POST['oubei_post_seo_nonce']) || !wp_verify_nonce(sanitize_text_field(wp_unslash($_POST['oubei_post_seo_nonce'])), 'oubei_save_post_seo') || !current_user_can('edit_post', $post_id)) { return; } update_post_meta($post_id, '_oubei_seo_title', sanitize_text_field(wp_unslash($_POST['oubei_seo_title'] ?? ''))); update_post_meta($post_id, '_oubei_seo_description', sanitize_textarea_field(wp_unslash($_POST['oubei_seo_description'] ?? ''))); });
